def ale(sle, aro):
    return sle * aro


risks = [
    {"name": "phishing_ransomware", "sle": 250000, "aro": 0.35, "control_cost": 40000},
    {"name": "single_disk_failure", "sle": 8000, "aro": 1.5, "control_cost": 15000},
]

for risk in risks:
    annual_loss = ale(risk["sle"], risk["aro"])
    decision = "mitigar" if annual_loss > risk["control_cost"] else "aceptar"
    print(f"{risk['name']}: ALE=${annual_loss:,.2f} costo_control=${risk['control_cost']:,.2f} decision={decision}")
